import{z as A,x as d,o,c as s,q as n,j as i,D as l,d as E,s as r,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"MoE 推理批处理","description":"","frontmatter":{"title":"MoE 推理批处理","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-inference-batching.md","filePath":"llm/moe-inference-batching.md","lastUpdated":1791063341000}'),p={name:"llm/moe-inference-batching.md"};function m(c,e,M,h,k,f){const t=d("Mermaid");return o(),s("div",null,[e[2]||(e[2]=n('<h1 id="moe-推理批处理" tabindex="-1">MoE 推理批处理 <a class="header-anchor" href="#moe-推理批处理" aria-label="Permalink to &quot;MoE 推理批处理&quot;">​</a></h1><div class="epigraph"><p>训练时专家靠巨大的 token 海填满；decode 每步每请求只有一个 token，专家侧的 GEMM 会瘦到算不动，除非把并发与路由凑成专家批。</p><footer>—— Shazeer et al., 2017；GShard：Lepikhin et al., 2020；推理侧对照 Mixtral 与 DeepSeek-V2/V3 的部署叙述</footer></div><p><a href="/llm/nccl-tuning">上一课</a>调的是稠密 TP 的 All-Reduce。MoE 还要 all-to-all：token 按<a href="/llm/moe-routing">路由</a>送到专家所在的 rank。<a href="/llm/arithmetic-intensity-decode">会计</a>说过只加载被点到的专家；decode 上若每个专家只分到 0–2 个 token，既搬了专家权重，又做不了胖 GEMM。本课写推理如何把 <em>专家维的 batch</em> 凑起来：连续批加大 \\(B\\)、同一 token 的 top-\\(k\\) 专家、以及 EP 切分。不重推门控公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稠密 MLP 的 decode 已经瘦；MoE 把瘦 GEMM 再拆到 \\(E\\) 个专家上，每个更瘦。Mixtral 一类 \\(k=2\\)，每 token 两次专家 FFN，权重大、复用差。缺口是：服务并发必须高到「每个被点中的专家都有足够 token」，否则 MoE 的「稀疏计算」变成「稀疏且更不适合 GPU」。容量因子、drop token 在推理上通常不允许丢用户 token，溢出只能走共享专家或本地备份，形状更碎。</p><p><span class="marginnote">术语翻译：「胖 GEMM」就是 batch 维行数足够多的矩阵乘。GPU 的算力只有在矩阵够「胖」时才喂得饱——行数太少时，时间都花在把权重从显存搬进计算单元上（带宽瓶颈），计算单元反而闲着。</span></p><p>EP（专家并行）把专家分到卡上，all-to-all 体积随 \\(B\\) 升。\\(B\\) 太小，通信启动开销与自定义 AR 同一类病；\\(B\\) 太大，KV 容量墙先到。MoE 服务的拐点比稠密更苛刻。</p><p><span class="marginnote">Prefill 天然有 \\(n\\) 个 token，专家批好凑，MoE 在 TTFT 上往往比 decode 好看。用 prefill 的加速比宣传 decode 会骗人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优先用连续批把 decode \\(B\\) 堆到专家 GEMM 可吃的程度；再考虑把同一拍的 prefill 切片混入（提高专家批，但 TPOT 抖动）。共享专家（DeepSeek 一类）每 token 必算，形状稳定，应单独走稠密核。路由输出做成 permutation + 分段 GEMM，而不是 \\(E\\) 次启动。能融合的专家核（Triton 按专家分块）减少启动。all-to-all 走 NCCL，体积过小同样考虑融合或延迟发送（会伤延迟）。</p>',10)),(o(),i(B,null,{default:l(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E6%9C%AC%E6%8B%8D%20B%20%E4%B8%AA%20decode%20token%22%5D%20--%3E%20GATE%5B%22%E8%B7%AF%E7%94%B1%20top-k%22%5D%0A%20%20GATE%20--%3E%20A2A%5B%22all-to-all%20%E5%88%B0%E4%B8%93%E5%AE%B6%22%5D%0A%20%20A2A%20--%3E%20EG%5B%22%E4%B8%93%E5%AE%B6%E4%BE%A7%E6%8B%BC%E6%89%B9%20GEMM%22%5D%0A%20%20EG%20--%3E%20A2A2%5B%22all-to-all%20%E5%9B%9E%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[E("稀疏对 "),a("em",null,"计算量"),E(" 成立，对 "),a("em",null,"权重搬运"),E(" 只在「点中的专家」上成立。点中集合若几乎覆盖全部专家（\\(B\\) 大、\\(k\\ge 2\\)），稀疏的搬运优势消失，只剩参数容量优势。这是 MoE 推理与训练的不对称：训练 \\(B\\) 巨大，推理 \\(B\\) 受 KV 限制。MLA 减 KV 正是为了让 MoE 服务能堆更大 \\(B\\)，从而专家批和屋顶线一起好过。")],-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(E=8\\)、\\(k=2\\)、\\(B=16\\) 时，16 个 token 各挑 2 个专家，8 个专家几乎人人被点中——8 份专家权重一份都躲不掉，只换来平均每专家 4 个 token 的瘦 GEMM；\\(B\\) 小到 1 时只有 2 份权重要搬，但搬完也只服务 1 个 token。两头都不讨好的区间就是本课要靠凑批逃出去的地方。")],-1)),(o(),i(B,null,{default:l(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%7B%22decode%20%E5%B9%B6%E5%8F%91%20B%20%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22B%20%E5%BE%88%E5%B0%8F%22%7C%20SMALL%5B%22%E6%AF%8F%E4%B8%93%E5%AE%B6%E5%8F%AA%E5%88%86%E5%88%B0%200-2%20%E4%B8%AA%20token%EF%BC%9A%E6%9D%83%E9%87%8D%E7%85%A7%E6%90%AC%E3%80%81GEMM%20%E7%98%A6%22%5D%0A%20%20B%20--%3E%7C%22%E4%B8%AD%E7%AD%89%22%7C%20MID%5B%22%E7%82%B9%E4%B8%AD%E9%9B%86%E5%90%88%E9%83%A8%E5%88%86%E9%87%8D%E5%8F%A0%EF%BC%9A%E7%A8%80%E7%96%8F%E6%90%AC%E8%BF%90%E4%BC%98%E5%8A%BF%E5%B0%9A%E5%AD%98%22%5D%0A%20%20B%20--%3E%7C%22%E5%BE%88%E5%A4%A7%22%7C%20BIG%5B%22%E5%87%A0%E4%B9%8E%E8%A6%86%E7%9B%96%E5%85%A8%E9%83%A8%E4%B8%93%E5%AE%B6%EF%BC%9A%E6%9D%83%E9%87%8D%E5%85%A8%E8%A6%81%E6%90%AC%EF%BC%8C%E5%8F%AA%E5%89%A9%E5%AE%B9%E9%87%8F%E4%BC%98%E5%8A%BF%22%5D%0A%20%20SMALL%20--%3E%20FIX%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E8%BF%9E%E7%BB%AD%E6%89%B9%E5%A0%86%20B%20%2F%20%E9%87%8F%E5%8C%96%E4%B8%93%E5%AE%B6%E6%9D%83%E9%87%8D%20%2F%20%E6%B7%B7%E5%85%A5%20prefill%20%E5%88%87%E7%89%87%22%5D%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 \\(B=1\\) 的单用户笔记本上期待 Mixtral 相对同激活量稠密模型大幅更快——搬运两项专家权重可能更慢。<span class="marginnote">常见误区：初学者容易以为「MoE 总参数大，推理就一定更贵」。按 FLOPs 算它确实只激活一小部分专家，计算量不大；但 decode 的瓶颈常在权重搬运，凑不齐专家批时，反而比同激活量的稠密模型更慢。</span>量化专家权重减字节，对 decode MoE 特别对症。下一课离开 GPU 矩阵，处理分词并行：CPU 侧不要成为逐步同步点。</p><p>出处：Shazeer et al., 2017；Lepikhin et al., 2020；Mixtral、DeepSeek-V2/V3 报告中的推理部署。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>decode MoE 的瓶颈是专家侧瘦 GEMM 与 all-to-all 启动。</li><li>用并发把专家批凑厚；prefill 好看不能代替 decode。</li><li>共享专家走稠密核；路由用 permutation 而不是 \\(E\\) 次启动。</li><li>\\(B\\) 受 KV 限制，减 KV 才能堆 MoE 服务。</li><li>稀疏计算 ≠ 稀疏搬运。</li><li>下一课：分词并行与预处理。</li><li>出处：Shazeer et al., 2017；Lepikhin et al., 2020。</li></ul>',5))])}const C=A(p,[["render",m]]);export{u as __pageData,C as default};
